    94→// CondenseSession condenses a session's shadow branch to permanent storage.
    95→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
    96→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
    97→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
    98→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID string, state *SessionState) (*CondenseResult, error) {
    99→	// Get shadow branch
   100→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
   101→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   102→	ref, err := repo.Reference(refName, true)
   103→	if err != nil {
   104→		return nil, fmt.Errorf("shadow branch not found: %w", err)
   105→	}
   106→
   107→	// Extract session data, starting from where we left off last condensation
   108→	// Use tracked files from session state instead of collecting all files from tree
   109→	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini)
   110→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.CondensedTranscriptLines, state.FilesTouched, state.AgentType)
   111→	if err != nil {
   112→		return nil, fmt.Errorf("failed to extract session data: %w", err)
   113→	}
   114→
   115→	// Get checkpoint store
   116→	store, err := s.getCheckpointStore()
   117→	if err != nil {
   118→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
   119→	}
   120→
   121→	// Get author info
   122→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   123→
   124→	// Get current branch name
   125→	branchName := GetCurrentBranchName(repo)
   126→
   127→	// Write checkpoint metadata using the checkpoint store
   128→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
   129→		CheckpointID:           checkpointID,
   130→		SessionID:              state.SessionID,
   131→		Strategy:               StrategyNameManualCommit,
   132→		Branch:                 branchName,
   133→		Transcript:             sessionData.Transcript,
   134→		Prompts:                sessionData.Prompts,
   135→		Context:                sessionData.Context,
   136→		FilesTouched:           sessionData.FilesTouched,
   137→		CheckpointsCount:       state.CheckpointCount,
   138→		EphemeralBranch:        shadowBranchName,
   139→		AuthorName:             authorName,
   140→		AuthorEmail:            authorEmail,
   141→		Agent:                  state.AgentType,
   142→		TranscriptUUIDAtStart:  state.TranscriptUUIDAtStart,
   143→		TranscriptLinesAtStart: state.TranscriptLinesAtStart,
   144→		TokenUsage:             sessionData.TokenUsage,
   145→	}); err != nil {
   146→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
   147→	}
   148→
   149→	return &CondenseResult{
   150→		CheckpointID:         checkpointID,
   151→		SessionID:            state.SessionID,
   152→		CheckpointsCount:     state.CheckpointCount,
   153→		FilesTouched:         sessionData.FilesTouched,
   154→		TotalTranscriptLines: sessionData.FullTranscriptLines,
   155→	}, nil
   156→}
