    94→// checkConcurrentSessions checks for concurrent session conflicts and shows warnings if needed.
    95→// Returns true if the hook should be skipped due to an unresolved conflict.
    96→func checkConcurrentSessions(ag agent.Agent, entireSessionID string) (bool, error) {
    97→	// Check if warnings are disabled via settings
    98→	if IsMultiSessionWarningDisabled() {
    99→		return false, nil
   100→	}
   101→
   102→	strat := GetStrategy()
   103→
   104→	concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker)
   105→	if !ok {
   106→		return false, nil // Strategy doesn't support concurrent checks
   107→	}
   108→
   109→	// Check if this session already acknowledged the warning
   110→	existingState, loadErr := strategy.LoadSessionState(entireSessionID)
   111→	warningAlreadyShown := loadErr == nil && existingState != nil && existingState.ConcurrentWarningShown
   112→
   113→	// Check for other active sessions with checkpoints (on current HEAD)
   114→	otherSession, checkErr := concurrentChecker.HasOtherActiveSessionsWithCheckpoints(entireSessionID)
   115→	hasConflict := checkErr == nil && otherSession != nil
   116→
   117→	if warningAlreadyShown {
   118→		if hasConflict {
   119→			// Warning was shown and conflict still exists - skip hooks
   120→			return true, nil
   121→		}
   122→		// Warning was shown but conflict is resolved (e.g., user committed)
   123→		// Clear the flag and proceed normally
   124→		if existingState != nil {
   125→			existingState.ConcurrentWarningShown = false
   126→			if saveErr := strategy.SaveSessionState(existingState); saveErr != nil {
   127→				fmt.Fprintf(os.Stderr, "Warning: failed to clear concurrent warning flag: %v\n", saveErr)
   128→			}
   129→		}
   130→		return false, nil
   131→	}
   132→
   133→	if hasConflict {
   134→		// First time seeing conflict - show warning
   135→		// Include BaseCommit and WorktreePath so session state is complete for condensation
   136→		repo, err := strategy.OpenRepository()
   137→		if err != nil {
   138→			// Output user-friendly error message via hook response
   139→			if outputErr := outputHookResponse(false, fmt.Sprintf("Failed to open git repository: %v\n\nPlease ensure you're in a git repository and try again.", err)); outputErr != nil {
   140→				return false, outputErr
   141→			}
   142→			return true, nil // Skip hook after outputting response
   143→		}
   144→		head, err := repo.Head()
   145→		if err != nil {
   146→			// Output user-friendly error message via hook response
   147→			if outputErr := outputHookResponse(false, fmt.Sprintf("Failed to get git HEAD: %v\n\nPlease ensure the repository has at least one commit.", err)); outputErr != nil {
   148→				return false, outputErr
   149→			}
   150→			return true, nil // Skip hook after outputting response
   151→		}
   152→		worktreePath, err := strategy.GetWorktreePath()
   153→		if err != nil {
   154→			// Non-fatal: continue without worktree path
   155→			worktreePath = ""
   156→		}
   157→		// Derive agent type from agent description (e.g., "Claude Code" from "Claude Code - ...")
   158→		agentType := ag.Description()
   159→		if idx := strings.Index(agentType, " - "); idx > 0 {
   160→			agentType = agentType[:idx]
   161→		}
   162→		newState := &strategy.SessionState{
   163→			SessionID:              entireSessionID,
   164→			BaseCommit:             head.Hash().String(),
   165→			WorktreePath:           worktreePath,
   166→			ConcurrentWarningShown: true,
   167→			StartedAt:              time.Now(),
   168→			AgentType:              agentType,
   169→		}
   170→		if saveErr := strategy.SaveSessionState(newState); saveErr != nil {
   171→			fmt.Fprintf(os.Stderr, "Warning: failed to save session state: %v\n", saveErr)
   172→		}
   173→
   174→		// Get resume command for the other session using the CONFLICTING session's agent type.
   175→		// If the conflicting session is from a different agent (e.g., Gemini when we're Claude),
   176→		// use that agent's resume command format. Otherwise, use our own format (backward compatible).
   177→		var resumeCmd string
   178→		if otherSession.AgentType != "" && otherSession.AgentType != agentType {
