// Detect attempts to auto-detect which agent is being used.
// Checks the default agent first (Claude Code), then others in sorted order.
// This ensures deterministic behavior when multiple agents are configured.
//
//nolint:ireturn // Factory pattern requires returning the interface
func Detect() (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	// Check default agent first for deterministic behavior
	if factory, ok := registry[DefaultAgentName]; ok {
		ag := factory()
		if present, err := ag.DetectPresence(); err == nil && present {
			return ag, nil
		}
	}

	// Check remaining agents in sorted order for determinism
	names := make([]string, 0, len(registry))
	for name := range registry {
		if name != DefaultAgentName {
			names = append(names, name)
		}
	}
	sort.Strings(names)

	for _, name := range names {
		ag := registry[name]()
		if present, err := ag.DetectPresence(); err == nil && present {
			return ag, nil
		}
	}
	return nil, fmt.Errorf("no agent detected (available: %v)", List())
}

