func TestGetCurrentHookAgent_FallbackWhenNotInHookContext(t *testing.T) {
	// Ensure currentHookAgentName is empty (not in hook context)
	currentHookAgentName = ""

	// Create a temp directory with .claude directory for detection
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	// Create .claude directory so Claude Code is detected
	if err := os.MkdirAll(".claude", 0o755); err != nil {
		t.Fatalf("failed to create .claude directory: %v", err)
	}

	ag, err := GetCurrentHookAgent()
	if err != nil {
		t.Fatalf("GetCurrentHookAgent() error = %v", err)
	}

	// Should fall back to GetAgent() which will detect based on directory
	// Since we created .claude, it should detect claude-code (though order is non-deterministic
	// if both .claude and .gemini exist - that's the bug this fix addresses!)
	if ag == nil {
		t.Error("GetCurrentHookAgent() returned nil agent")
	}
}

func TestGetCurrentHookAgent_SetByHookCommand(t *testing.T) {
	// This test verifies that newAgentHookVerbCmdWithLogging sets currentHookAgentName
	// before calling the handler

	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	// Initialize git repo (required for paths.RepoRoot to work)
	gitInit := exec.CommandContext(context.Background(), "git", "init")
	if err := gitInit.Run(); err != nil {
		t.Fatalf("failed to init git repo: %v", err)
	}

	// Track what agent was seen inside the handler
	var agentSeenInHandler string
	RegisterHookHandler("test-agent-context", "test-hook-context", func() error {
		ag, err := GetCurrentHookAgent()
		if err != nil {
			return err
		}
		agentSeenInHandler = ag.Name()
		return nil
	})

	// Create and execute a command for claude-code
	cmd := newAgentHookVerbCmdWithLogging(agent.AgentNameClaudeCode, "test-hook-context")
	RegisterHookHandler(agent.AgentNameClaudeCode, "test-hook-context", func() error {
		ag, err := GetCurrentHookAgent()
		if err != nil {
			return err
		}
		agentSeenInHandler = ag.Name()
		return nil
	})

	if err := cmd.Execute(); err != nil {
		t.Fatalf("command execution failed: %v", err)
	}

	if agentSeenInHandler != agent.AgentNameClaudeCode {
		t.Errorf("handler saw agent %q, want %q", agentSeenInHandler, agent.AgentNameClaudeCode)
	}

	// Reset and test with gemini
	agentSeenInHandler = ""
	RegisterHookHandler(agent.AgentNameGemini, "test-hook-context", func() error {
		ag, err := GetCurrentHookAgent()
		if err != nil {
			return err
		}
		agentSeenInHandler = ag.Name()
		return nil
	})

	cmd = newAgentHookVerbCmdWithLogging(agent.AgentNameGemini, "test-hook-context")
	if err := cmd.Execute(); err != nil {
		t.Fatalf("command execution failed: %v", err)
	}

	if agentSeenInHandler != agent.AgentNameGemini {
		t.Errorf("handler saw agent %q, want %q", agentSeenInHandler, agent.AgentNameGemini)
	}
}

func TestGetCurrentHookAgent_ClearedAfterHandler(t *testing.T) {
	// Verify that currentHookAgentName is cleared after the handler completes
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	// Initialize git repo
	gitInit := exec.CommandContext(context.Background(), "git", "init")
	if err := gitInit.Run(); err != nil {
		t.Fatalf("failed to init git repo: %v", err)
	}

	RegisterHookHandler(agent.AgentNameClaudeCode, "test-hook-cleanup", func() error {
		// Inside handler, currentHookAgentName should be set
		if currentHookAgentName != agent.AgentNameClaudeCode {
			t.Errorf("inside handler: currentHookAgentName = %q, want %q", currentHookAgentName, agent.AgentNameClaudeCode)
		}
		return nil
	})

	cmd := newAgentHookVerbCmdWithLogging(agent.AgentNameClaudeCode, "test-hook-cleanup")
	if err := cmd.Execute(); err != nil {
		t.Fatalf("command execution failed: %v", err)
	}

	// After handler completes, currentHookAgentName should be cleared
	if currentHookAgentName != "" {
		t.Errorf("after handler: currentHookAgentName = %q, want empty string", currentHookAgentName)
	}
}

